<?php use App\Core\Csrf; $statuses = App\Services\TaskService::STATUSES; ?>
<h1>Tasks</h1>
<?php if ($manageable): ?><details class="card"><summary>Create a task</summary><form method="post" action="<?= e(url('/tasks')) ?>"><?= Csrf::field() ?>
<label for="tp">Project</label><select id="tp" name="project_id"><?php foreach ($manageable as $p): ?><option value="<?= (int) $p['id'] ?>"><?= e($p['name']) ?></option><?php endforeach; ?></select>
<label for="tt">Title</label><input id="tt" name="title" maxlength="180" required><label for="td">Description</label><textarea id="td" name="description"></textarea>
<div class="grid grid-3"><div><label for="tdue">Due date</label><input id="tdue" type="date" name="due_date"></div><div><label for="tst">Status</label><select id="tst" name="status"><?php foreach ($statuses as $s): ?><option value="<?= $s ?>"><?= e(label($s)) ?></option><?php endforeach; ?></select></div>
<div><label for="ta">Assign to</label><select id="ta" name="assigned_assignment_id"><option value="">Unassigned</option><?php foreach ($assignable as $pid => $list): foreach ($list as $x): ?><option value="<?= (int) $x['id'] ?>"><?= e($x['full_name']) ?> (project #<?= (int) $pid ?>)</option><?php endforeach; endforeach; ?></select></div></div>
<p class="hint">The assignee must be serving on the chosen project.</p><div class="actions"><button class="btn">Create task</button></div></form></details><?php endif; ?>
<div class="card table-wrap"><?php if (!$rows): ?><p class="empty">No tasks.</p><?php else: ?><table><thead><tr><th>Task</th><th>Project</th><th>Assignee</th><th>Due</th><th>Status</th><?= $manageable ? '<th>Update</th>' : '' ?></tr></thead><tbody>
<?php foreach ($rows as $t): $can = App\Security\Auth::isAdmin() || App\Security\Auth::supervises((int) $t['project_id']); ?><tr><td><?= e($t['title']) ?><?= $t['description'] ? '<br><span class="muted">' . e($t['description']) . '</span>' : '' ?></td><td><?= e($t['project_name']) ?></td><td><?= e($t['assignee'] ?? '—') ?></td><td><?= e(fmt_date($t['due_date'])) ?></td><td><?= e(label($t['status'])) ?></td>
<?php if ($manageable): ?><td><?php if ($can): ?><form method="post" action="<?= e(url('/tasks')) ?>" class="filters"><?= Csrf::field() ?><input type="hidden" name="task_id" value="<?= (int) $t['id'] ?>"><input type="hidden" name="project_id" value="<?= (int) $t['project_id'] ?>">
<input type="hidden" name="title" value="<?= e($t['title']) ?>"><input type="hidden" name="description" value="<?= e($t['description']) ?>"><input type="hidden" name="due_date" value="<?= e($t['due_date']) ?>"><input type="hidden" name="assigned_assignment_id" value="<?= e($t['assigned_assignment_id']) ?>">
<select name="status" aria-label="Status"><?php foreach ($statuses as $s): ?><option value="<?= $s ?>"<?= $t['status'] === $s ? ' selected' : '' ?>><?= e(label($s)) ?></option><?php endforeach; ?></select><button class="btn small">Save</button></form><?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table><?php endif; ?></div>
